begin;
create extension if not exists pgtap with schema extensions;
set local search_path = extensions, public;
select plan(19);
select has_function('public', 'confirm_batch', array['text','uuid','uuid[]'], 'confirmation RPC exists');
-- Fabricated identities only; all schema and fixture changes are rolled back.
insert into auth.users(id) values ('10000000-0000-4000-8000-000000000061'), ('10000000-0000-4000-8000-000000000062');
insert into public.devices(id,owner_id,name,last_seen_at) values ('60000000-0000-4000-8000-000000000061','10000000-0000-4000-8000-000000000061','Executor fictício',now());
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000061","role":"authenticated"}',true);
insert into public.responsibles(id,name,document) values ('20000000-0000-4000-8000-000000000061','Responsável fictício','99988877000108');
insert into public.taxpayers(id,responsible_id,name,document) values ('30000000-0000-4000-8000-000000000061','20000000-0000-4000-8000-000000000061','Empresa fictícia','27182818000129');
insert into public.simple_profiles(taxpayer_id,activity,tax_option) values ('30000000-0000-4000-8000-000000000061','commerce','Varejo');
insert into public.taxpayer_obligations(taxpayer_id,obligation) values ('30000000-0000-4000-8000-000000000061','simples');
insert into public.monthly_assessments(id,taxpayer_id,obligation,competence,revenue_cents) values ('40000000-0000-4000-8000-000000000061','30000000-0000-4000-8000-000000000061','simples','2026-09',12345);
select set_config('test.confirmed',public.confirm_batch('2026-09','60000000-0000-4000-8000-000000000061',array['40000000-0000-4000-8000-000000000061']::uuid[])::text,true);
select is((current_setting('test.confirmed')::jsonb->>'itemCount')::int,1,'returns count');
select is((current_setting('test.confirmed')::jsonb->>'totalRevenueCents')::bigint,12345::bigint,'returns integer cents');
select is((select competence from public.batch_items),'2026-09','copies competence');
select is((select activity::text from public.batch_items),'commerce','copies activity');
select is((select responsible_name from public.batch_items),'Responsável fictício','copies responsible');
select is((select taxpayer_document from public.batch_items),'27182818000129','copies taxpayer document');
update public.monthly_assessments set revenue_cents=67890;
update public.responsibles set name='Responsável alterado';
update public.simple_profiles set activity='services';
select is((select revenue_cents from public.batch_items),12345::bigint,'assessment edit cannot change snapshot');
select is((select responsible_name from public.batch_items),'Responsável fictício','responsible edit cannot change snapshot');
select isnt(public.confirm_batch('2026-09','60000000-0000-4000-8000-000000000061',array['40000000-0000-4000-8000-000000000061']::uuid[])->>'batchId',current_setting('test.confirmed')::jsonb->>'batchId','second confirmation creates distinct batch');
select throws_ok($$update public.batch_items set revenue_cents=0$$,'42501',null,'client cannot mutate snapshot');
select throws_ok($$select public.confirm_batch('2026-08','60000000-0000-4000-8000-000000000061',array['40000000-0000-4000-8000-000000000061']::uuid[])$$,'22023',null,'rejects mismatched competence');
select throws_ok($$select public.confirm_batch('2026-09','60000000-0000-4000-8000-000000000061',array['40000000-0000-4000-8000-000000000061','40000000-0000-4000-8000-000000000061']::uuid[])$$,'22023',null,'rejects duplicate assessments');
update public.taxpayer_obligations set active=false;
select throws_ok($$select public.confirm_batch('2026-09','60000000-0000-4000-8000-000000000061',array['40000000-0000-4000-8000-000000000061']::uuid[])$$,'22023',null,'rejects inactive profile obligation');
select is((select count(*) from public.batches),2::bigint,'invalid requests create no partial batch');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000062","role":"authenticated"}',true);
select is((select count(*) from public.batch_items),0::bigint,'foreign owner cannot read items');
select throws_ok($$select public.confirm_batch('2026-09','60000000-0000-4000-8000-000000000061',array['40000000-0000-4000-8000-000000000061']::uuid[])$$,'22023',null,'foreign owner cannot confirm');
select is((select count(*) from public.batches),0::bigint,'foreign owner cannot read batches');
reset role;
set local role anon;
select throws_ok($$select public.confirm_batch('2026-09','60000000-0000-4000-8000-000000000061',array['40000000-0000-4000-8000-000000000061']::uuid[])$$,'42501',null,'anonymous cannot confirm');
reset role;
select * from finish();
rollback;
